Here is an expense tracker for October: add each spend with a category, and it totals the month and shows where the money went. Entries stay only while this page is open.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#fafafa;color:#222}
  h2{margin:0 0 12px;font-size:18px}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
  input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
  input{flex:1;min-width:110px}
  button{background:#2f7d5b;color:#fff;border-color:#2f7d5b;cursor:pointer}
  button.x{background:none;color:#b00;border:none;padding:2px 6px}
  .card{background:#fff;border:1px solid #e5e5e5;border-radius:8px;padding:12px;margin-bottom:12px}
  .big{font-size:24px;font-weight:600}
  .bar{height:8px;background:#2f7d5b;border-radius:4px}
  .cat{margin:6px 0;font-size:13px}
  .cat div.top{display:flex;justify-content:space-between}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #f0f0f0;font-size:14px}
  .muted{color:#777;font-size:12px}
  .over{color:#b00}
</style>
</head>
<body>
<h2>Expenses: October 2026</h2>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin:8px 0 0">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹), optional">
  </div>
  <div class="muted" id="left"></div>
</div>

<div class="row">
  <input id="desc" placeholder="What was it?">
  <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  <select id="cat">
    <option>Food</option><option>Travel</option><option>Bills</option>
    <option>Shopping</option><option>Health</option><option>Other</option>
  </select>
  <button id="add">Add</button>
</div>

<div class="card"><div class="muted">By category</div><div id="cats"></div></div>
<div class="card"><div class="muted">All entries</div><div id="list"></div></div>

<script>
var items=[];
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function render(){
  var total=0,by={};
  items.forEach(function(i){total+=i.amt;by[i.cat]=(by[i.cat]||0)+i.amt;});
  document.getElementById('total').textContent=inr(total);
  var b=parseFloat(document.getElementById('budget').value);
  var left=document.getElementById('left');
  if(b>0){
    var r=b-total;
    left.className='muted'+(r<0?' over':'');
    left.textContent=r>=0?inr(r)+' left of '+inr(b):inr(-r)+' over budget';
  }else{left.textContent='';}
  var c=document.getElementById('cats');
  var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a];});
  c.innerHTML=keys.length?keys.map(function(k){
    var p=total?by[k]/total*100:0;
    return '<div class="cat"><div class="top"><span>'+esc(k)+'</span><span>'+inr(by[k])+' ('+Math.round(p)+'%)</span></div><div class="bar" style="width:'+p+'%"></div></div>';
  }).join(''):'<div class="muted">Nothing yet</div>';
  var l=document.getElementById('list');
  l.innerHTML=items.length?items.map(function(i,idx){
    return '<div class="item"><span>'+esc(i.desc)+' <span class="muted">'+esc(i.cat)+'</span></span><span>'+inr(i.amt)+' <button class="x" data-i="'+idx+'">✕</button></span></div>';
  }).join(''):'<div class="muted">Nothing yet</div>';
}
document.getElementById('add').onclick=function(){
  var d=document.getElementById('desc'),a=document.getElementById('amt');
  var v=parseFloat(a.value);
  if(!(v>0))return;
  items.unshift({desc:d.value.trim()||'Expense',amt:v,cat:document.getElementById('cat').value});
  d.value='';a.value='';d.focus();render();
};
document.getElementById('list').onclick=function(e){
  var i=e.target.getAttribute('data-i');
  if(i!==null){items.splice(parseInt(i,10),1);render();}
};
document.getElementById('budget').oninput=render;
render();
</script>
</body>
</html>
```

Here's your water tracker, with a goal of 8 glasses. Tap a glass to fill it, or use the buttons below.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: sans-serif; text-align: center; padding: 16px; background: #eef7fb; color: #12394d; }
  h2 { margin: 0 0 4px; }
  .date { font-size: 13px; opacity: .7; margin-bottom: 12px; }
  .count { font-size: 40px; font-weight: bold; margin: 8px 0; }
  .bar { height: 12px; background: #cfe6f0; border-radius: 6px; overflow: hidden; margin: 8px auto 16px; max-width: 320px; }
  .fill { height: 100%; width: 0; background: #2a9fd6; transition: width .3s; }
  .glasses { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; max-width: 320px; margin: 0 auto 16px; }
  .glass { height: 56px; border: 2px solid #2a9fd6; border-radius: 4px 4px 12px 12px; background: #fff; cursor: pointer; }
  .glass.on { background: #2a9fd6; }
  button { font-size: 16px; padding: 8px 16px; margin: 4px; border: 0; border-radius: 8px; background: #2a9fd6; color: #fff; cursor: pointer; }
  button.alt { background: #8aa7b5; }
  .msg { min-height: 24px; margin-top: 10px; font-weight: bold; }
</style>
</head>
<body>
  <h2>Water today</h2>
  <div class="date">Tue 27 Oct 2026</div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="f"></div></div>
  <div class="glasses" id="g"></div>
  <button id="add">+ Add a glass</button>
  <button id="sub" class="alt">- Remove</button>
  <button id="reset" class="alt">Reset</button>
  <div class="msg" id="m"></div>
<script>
  var GOAL = 8, count = 0;
  var key = "water-2026-10-27";
  try { count = parseInt(localStorage.getItem(key)) || 0; } catch (e) {}
  var g = document.getElementById("g");
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var d = document.createElement("div");
      d.className = "glass";
      d.onclick = function () { count = (count === i + 1) ? i : i + 1; draw(); };
      g.appendChild(d);
    })(i);
  }
  function draw() {
    count = Math.max(0, Math.min(GOAL, count));
    document.getElementById("n").textContent = count;
    document.getElementById("f").style.width = (count / GOAL * 100) + "%";
    var gl = g.children;
    for (var i = 0; i < gl.length; i++) gl[i].className = "glass" + (i < count ? " on" : "");
    document.getElementById("m").textContent =
      count >= GOAL ? "Goal reached. Well done! 💧" : (GOAL - count) + " more to go";
    try { localStorage.setItem(key, count); } catch (e) {}
  }
  document.getElementById("add").onclick = function () { count++; draw(); };
  document.getElementById("sub").onclick = function () { count--; draw(); };
  document.getElementById("reset").onclick = function () { count = 0; draw(); };
  draw();
</script>
</body>
</html>
```
